const WEEK10_CODES = {
  topic1: {
    title: "Stefan Tube, Log-Mean & Arnold-Cell D Measurement",
    python: "# Week 10 - Topic 1: Stefan Tube (Arnold Cell), Log-Mean, Film Model, Pseudo-Steady D Measurement\n# Lecture (Part 1):\n#   * steady 1D diffusion of A through stagnant B (N_Bz = 0):\n#       N_Az = -cD_AB/(1 - y_A) dy_A/dz = const\n#       N_Az = cD_AB/(z2 - z1) ln[(1 - y_A2)/(1 - y_A1)] = cD_AB (y_A1 - y_A2)/((z2 - z1) y_B,lm)\n#       y_B,lm = (y_B2 - y_B1)/ln(y_B2/y_B1)\n#   * profile: (1 - y_A)/(1 - y_A1) = [(1 - y_A2)/(1 - y_A1)]^((z - z1)/(z2 - z1))\n#   * film model: k_c = P D_AB/(delta p_B,lm)\n#   * pseudo-steady Arnold cell (liquid level falls slowly):\n#       rho_AL/M_A dz/dt = cD_AB (y_A1 - y_A2)/(z y_B,lm)\n#       -> t = rho_AL y_B,lm (z^2 - z0^2)/(2 c D_AB M_A (y_A1 - y_A2))\n#       -> D_AB from the slope of (z^2 - z0^2) versus t.\n\nimport math\nimport random\n\nR = 8.314462618\n\n# Antoine constants (log10 P[mmHg] = A - B/(C + T[degC]))\nANTOINE = {\"water\": (8.07131, 1730.63, 233.426),\n           \"ethanol\": (8.20417, 1642.89, 230.300),\n           \"acetone\": (7.02447, 1161.0, 224.0)}\n# liquid density (kg/m^3) and molar mass (g/mol) near 25 degC\nLIQ = {\"water\": (997.0, 18.015), \"ethanol\": (789.0, 46.07), \"acetone\": (784.0, 58.08)}\n# Fuller diffusion volumes from the Week 9 lecture table (C 16.5, H 1.98, O 5.48; H2O 12.7; air 20.1)\nVOL = {\"water\": 12.7, \"ethanol\": 2 * 16.5 + 6 * 1.98 + 5.48, \"acetone\": 3 * 16.5 + 6 * 1.98 + 5.48, \"air\": 20.1}\n\n\ndef psat(liq, T_C):\n    A, B, C = ANTOINE[liq]\n    return 10 ** (A - B / (C + T_C)) * 133.322   # Pa\n\n\ndef fuller(liq, T_K, P_atm=1.0):\n    Ma, Mb = LIQ[liq][1], 28.97\n    den = (VOL[liq] ** (1 / 3) + VOL[\"air\"] ** (1 / 3)) ** 2\n    return 1.011e-3 * T_K ** 1.75 * math.sqrt(1 / Ma + 1 / Mb) / (P_atm * den) * 1e-4   # m^2/s\n\n\ndef ylm(yA1, yA2):\n    yB1, yB2 = 1 - yA1, 1 - yA2\n    return (yB2 - yB1) / math.log(yB2 / yB1) if abs(yB2 - yB1) > 1e-12 else yB1\n\n\ndef stefan_flux(c, D, L, yA1, yA2):\n    return c * D / L * math.log((1 - yA2) / (1 - yA1))\n\n\ndef profile(z, L, yA1, yA2):\n    return 1 - (1 - yA1) * ((1 - yA2) / (1 - yA1)) ** (z / L)\n\n\nif __name__ == \"__main__\":\n    P, T_C = 101325.0, 25.0\n    T = T_C + 273.15\n    c = P / (R * T)\n    L = 0.10                                   # 10 cm tube\n    print(f\"Stefan tube, L = {L*100:.0f} cm, {T_C} C, 1 atm, c = {c:.3f} mol/m^3\")\n    print(\" liquid    p_sat(kPa)  y_A1    D(cm^2/s)  y_B,lm   N_A (mol/m^2 s)  Stefan/Fick\")\n    for liq in (\"water\", \"ethanol\", \"acetone\"):\n        yA1 = psat(liq, T_C) / P\n        D = fuller(liq, T)\n        N = stefan_flux(c, D, L, yA1, 0.0)\n        N_fick = c * D * yA1 / L\n        print(f\" {liq:<8} {psat(liq,T_C)/1e3:9.2f}  {yA1:6.4f}  {D*1e4:8.4f}  {ylm(yA1,0):7.4f}  {N:14.4e}  {N/N_fick:9.4f}\")\n\n    # check the two equivalent forms and the profile\n    yA1 = psat(\"acetone\", T_C) / P\n    D = fuller(\"acetone\", T)\n    N1 = stefan_flux(c, D, L, yA1, 0.0)\n    N2 = c * D * (yA1 - 0.0) / (L * ylm(yA1, 0.0))\n    print(f\"\\nlog form {N1:.6e} vs log-mean form {N2:.6e}\")\n    zs = [i * L / 1000 for i in range(1001)]\n    yB = [1 - profile(z, L, yA1, 0.0) for z in zs]\n    mean = sum((yB[i] + yB[i + 1]) / 2 for i in range(1000)) / 1000\n    print(f\"path-averaged y_B = {mean:.6f} equals y_B,lm = {ylm(yA1, 0.0):.6f}\")\n\n    # film model k_c\n    delta = 2e-3\n    kc = P * D / (delta * ylm(yA1, 0.0) * P)\n    print(f\"film model (delta = 2 mm): k_c = P D/(delta p_B,lm) = {kc*100:.3f} cm/s\")\n\n    # pseudo-steady Arnold cell: synthetic experiment and back-calculation of D\n    liq = \"water\"\n    rhoL, MA = LIQ[liq]\n    yA1 = psat(liq, T_C) / P\n    D_true = fuller(liq, T)\n    z0 = 0.02\n    K = 2 * c * D_true * MA * 1e-3 * yA1 / (rhoL * ylm(yA1, 0.0))   # z^2 - z0^2 = K t\n    random.seed(3)\n    days = [1, 2, 4, 6, 8, 10, 14]\n    data = []\n    for d in days:\n        t = d * 86400\n        z = math.sqrt(z0 ** 2 + K * t) + random.gauss(0, 2e-5)      # +-20 um reading noise\n        data.append((t, z))\n    xs = [t for t, _ in data]\n    ys = [z * z - z0 * z0 for _, z in data]\n    slope = sum(x * y for x, y in zip(xs, ys)) / sum(x * x for x in xs)  # fit through origin\n    D_fit = slope * rhoL * ylm(yA1, 0.0) / (2 * c * MA * 1e-3 * yA1)\n    print(f\"\\nArnold cell (water, z0 = 2 cm): level after 14 days z = {data[-1][1]*100:.3f} cm\")\n    print(f\"D_true = {D_true*1e4:.4f} cm^2/s, D from (z^2 - z0^2) vs t fit = {D_fit*1e4:.4f} cm^2/s\")\n",
    matlab: "% Week 10 - Topic 1: Stefan Tube (Arnold Cell), Log-Mean, Film Model, Pseudo-Steady D Measurement\n% Lecture (Part 1):\n%   * steady 1D diffusion of A through stagnant B (N_Bz = 0):\n%       N_Az = -cD_AB/(1 - y_A) dy_A/dz = const\n%       N_Az = cD_AB/(z2 - z1) ln[(1 - y_A2)/(1 - y_A1)] = cD_AB (y_A1 - y_A2)/((z2 - z1) y_B,lm)\n%       y_B,lm = (y_B2 - y_B1)/ln(y_B2/y_B1)\n%   * profile: (1 - y_A)/(1 - y_A1) = [(1 - y_A2)/(1 - y_A1)]^((z - z1)/(z2 - z1))\n%   * film model: k_c = P D_AB/(delta p_B,lm)\n%   * pseudo-steady Arnold cell (liquid level falls slowly):\n%       rho_AL/M_A dz/dt = cD_AB (y_A1 - y_A2)/(z y_B,lm)\n%       -> t = rho_AL y_B,lm (z^2 - z0^2)/(2 c D_AB M_A (y_A1 - y_A2))\n%       -> D_AB from the slope of (z^2 - z0^2) versus t.\nfunction week10_topic1_stefan_tube()\n    % name: Antoine A, B, C (mmHg, degC), rho_L (kg/m^3), M (g/mol), Fuller volume\n    Q.water   = [8.07131, 1730.63, 233.426, 997.0, 18.015, 12.7];\n    Q.ethanol = [8.20417, 1642.89, 230.300, 789.0, 46.07, 2*16.5 + 6*1.98 + 5.48];\n    Q.acetone = [7.02447, 1161.0, 224.0, 784.0, 58.08, 3*16.5 + 6*1.98 + 5.48];\n    R = 8.314462618; P = 101325; TC = 25; T = TC + 273.15; c = P/(R*T); L = 0.10;\n    psat = @(q, TC) 10.^(q(1) - q(2)./(q(3) + TC))*133.322;\n    fuller = @(q, TK) 1.011e-3*TK^1.75*sqrt(1/q(5) + 1/28.97)/((q(6)^(1/3) + 20.1^(1/3))^2)*1e-4;\n    ylm = @(y1, y2) ((1-y2) - (1-y1))/log((1-y2)/(1-y1));\n    flux = @(D, y1, y2) c*D/L*log((1-y2)/(1-y1));\n    prof = @(z, y1, y2) 1 - (1-y1)*((1-y2)/(1-y1)).^(z/L);\n\n    fprintf('Stefan tube, L = %.0f cm, %.1f C, 1 atm, c = %.3f mol/m^3\\n', L*100, TC, c);\n    fprintf(' liquid    p_sat(kPa)  y_A1    D(cm^2/s)  y_B,lm   N_A (mol/m^2 s)  Stefan/Fick\\n');\n    names = {'water', 'ethanol', 'acetone'};\n    for k = 1:3\n        q = Q.(names{k}); y1 = psat(q, TC)/P; D = fuller(q, T); N = flux(D, y1, 0);\n        fprintf(' %-8s %9.2f  %6.4f  %8.4f  %7.4f  %14.4e  %9.4f\\n', names{k}, psat(q,TC)/1e3, y1, D*1e4, ylm(y1,0), N, N/(c*D*y1/L));\n    end\n    q = Q.acetone; y1 = psat(q, TC)/P; D = fuller(q, T);\n    fprintf('\\nlog form %.6e vs log-mean form %.6e\\n', flux(D, y1, 0), c*D*y1/(L*ylm(y1, 0)));\n    z = linspace(0, L, 1001); yB = 1 - prof(z, y1, 0);\n    fprintf('path-averaged y_B = %.6f equals y_B,lm = %.6f\\n', trapz(z, yB)/L, ylm(y1, 0));\n    fprintf('film model (delta = 2 mm): k_c = P D/(delta p_B,lm) = %.3f cm/s\\n', D/(2e-3*ylm(y1, 0))*100);\n\n    % pseudo-steady Arnold cell: synthetic experiment and back-calculation of D\n    q = Q.water; y1 = psat(q, TC)/P; Dt = fuller(q, T); z0 = 0.02; rhoL = q(4); MA = q(5)*1e-3;\n    K = 2*c*Dt*MA*y1/(rhoL*ylm(y1, 0));\n    rng(3); days = [1 2 4 6 8 10 14]; t = days*86400;\n    zz = sqrt(z0^2 + K*t) + 2e-5*randn(size(t));\n    slope = sum(t.*(zz.^2 - z0^2))/sum(t.^2);\n    Dfit = slope*rhoL*ylm(y1, 0)/(2*c*MA*y1);\n    fprintf('\\nArnold cell (water, z0 = 2 cm): level after 14 days z = %.3f cm\\n', zz(end)*100);\n    fprintf('D_true = %.4f cm^2/s, D from (z^2 - z0^2) vs t fit = %.4f cm^2/s\\n', Dt*1e4, Dfit*1e4);\nend\n",
    julia: "# Week 10 - Topic 1: Stefan Tube (Arnold Cell), Log-Mean, Film Model, Pseudo-Steady D Measurement\n# Lecture (Part 1):\n#   * steady 1D diffusion of A through stagnant B (N_Bz = 0):\n#       N_Az = -cD_AB/(1 - y_A) dy_A/dz = const\n#       N_Az = cD_AB/(z2 - z1) ln[(1 - y_A2)/(1 - y_A1)] = cD_AB (y_A1 - y_A2)/((z2 - z1) y_B,lm)\n#       y_B,lm = (y_B2 - y_B1)/ln(y_B2/y_B1)\n#   * profile: (1 - y_A)/(1 - y_A1) = [(1 - y_A2)/(1 - y_A1)]^((z - z1)/(z2 - z1))\n#   * film model: k_c = P D_AB/(delta p_B,lm)\n#   * pseudo-steady Arnold cell (liquid level falls slowly):\n#       rho_AL/M_A dz/dt = cD_AB (y_A1 - y_A2)/(z y_B,lm)\n#       -> t = rho_AL y_B,lm (z^2 - z0^2)/(2 c D_AB M_A (y_A1 - y_A2))\n#       -> D_AB from the slope of (z^2 - z0^2) versus t.\nusing Printf, Random\n\nconst R = 8.314462618\n# Antoine A, B, C (mmHg, degC), rho_L (kg/m^3), M (g/mol), Fuller volume\nconst Q = Dict(\"water\" => (8.07131, 1730.63, 233.426, 997.0, 18.015, 12.7),\n               \"ethanol\" => (8.20417, 1642.89, 230.300, 789.0, 46.07, 2 * 16.5 + 6 * 1.98 + 5.48),\n               \"acetone\" => (7.02447, 1161.0, 224.0, 784.0, 58.08, 3 * 16.5 + 6 * 1.98 + 5.48))\n\npsat(n, TC) = (q = Q[n]; 10^(q[1] - q[2] / (q[3] + TC)) * 133.322)\nfuller(n, TK) = 1.011e-3 * TK^1.75 * sqrt(1 / Q[n][5] + 1 / 28.97) / (cbrt(Q[n][6]) + cbrt(20.1))^2 * 1e-4\nylm(y1, y2) = ((1 - y2) - (1 - y1)) / log((1 - y2) / (1 - y1))\nstefan_flux(c, D, L, y1, y2) = c * D / L * log((1 - y2) / (1 - y1))\nprofile(z, L, y1, y2) = 1 - (1 - y1) * ((1 - y2) / (1 - y1))^(z / L)\n\nP, TC = 101325.0, 25.0\nT = TC + 273.15; c = P / (R * T); L = 0.10\n@printf(\"Stefan tube, L = %.0f cm, %.1f C, 1 atm, c = %.3f mol/m^3\\n\", L * 100, TC, c)\nprintln(\" liquid    p_sat(kPa)  y_A1    D(cm^2/s)  y_B,lm   N_A (mol/m^2 s)  Stefan/Fick\")\nfor n in (\"water\", \"ethanol\", \"acetone\")\n    y1 = psat(n, TC) / P; D = fuller(n, T); N = stefan_flux(c, D, L, y1, 0.0)\n    @printf(\" %-8s %9.2f  %6.4f  %8.4f  %7.4f  %14.4e  %9.4f\\n\", n, psat(n, TC) / 1e3, y1, D * 1e4, ylm(y1, 0.0), N, N / (c * D * y1 / L))\nend\ny1 = psat(\"acetone\", TC) / P; D = fuller(\"acetone\", T)\n@printf(\"\\nlog form %.6e vs log-mean form %.6e\\n\", stefan_flux(c, D, L, y1, 0.0), c * D * y1 / (L * ylm(y1, 0.0)))\nzs = range(0, L, length = 1001); yB = [1 - profile(z, L, y1, 0.0) for z in zs]\n@printf(\"path-averaged y_B = %.6f equals y_B,lm = %.6f\\n\", sum((yB[1:end-1] .+ yB[2:end]) ./ 2) / 1000, ylm(y1, 0.0))\n@printf(\"film model (delta = 2 mm): k_c = P D/(delta p_B,lm) = %.3f cm/s\\n\", D / (2e-3 * ylm(y1, 0.0)) * 100)\n\n# pseudo-steady Arnold cell: synthetic experiment and back-calculation of D\nrhoL, MA = Q[\"water\"][4], Q[\"water\"][5] * 1e-3\ny1 = psat(\"water\", TC) / P; Dt = fuller(\"water\", T); z0 = 0.02\nK = 2 * c * Dt * MA * y1 / (rhoL * ylm(y1, 0.0))\nRandom.seed!(3)\nt = [1, 2, 4, 6, 8, 10, 14] .* 86400.0\nz = sqrt.(z0^2 .+ K .* t) .+ 2e-5 .* randn(length(t))\nslope = sum(t .* (z .^ 2 .- z0^2)) / sum(t .^ 2)\nDfit = slope * rhoL * ylm(y1, 0.0) / (2 * c * MA * y1)\n@printf(\"\\nArnold cell (water, z0 = 2 cm): level after 14 days z = %.3f cm\\n\", z[end] * 100)\n@printf(\"D_true = %.4f cm^2/s, D from (z^2 - z0^2) vs t fit = %.4f cm^2/s\\n\", Dt * 1e4, Dfit * 1e4)\n",
    cpp: "// Week 10 - Topic 1: Stefan Tube (Arnold Cell), Log-Mean, Film Model, Pseudo-Steady D Measurement\n// Lecture (Part 1):\n//   * steady 1D diffusion of A through stagnant B (N_Bz = 0):\n//       N_Az = -cD_AB/(1 - y_A) dy_A/dz = const\n//       N_Az = cD_AB/(z2 - z1) ln[(1 - y_A2)/(1 - y_A1)] = cD_AB (y_A1 - y_A2)/((z2 - z1) y_B,lm)\n//       y_B,lm = (y_B2 - y_B1)/ln(y_B2/y_B1)\n//   * profile: (1 - y_A)/(1 - y_A1) = [(1 - y_A2)/(1 - y_A1)]^((z - z1)/(z2 - z1))\n//   * film model: k_c = P D_AB/(delta p_B,lm)\n//   * pseudo-steady Arnold cell (liquid level falls slowly):\n//       rho_AL/M_A dz/dt = cD_AB (y_A1 - y_A2)/(z y_B,lm)\n//       -> t = rho_AL y_B,lm (z^2 - z0^2)/(2 c D_AB M_A (y_A1 - y_A2))\n//       -> D_AB from the slope of (z^2 - z0^2) versus t.\n\n// Build: g++ -O2 -std=c++17 week10_topic1_stefan_tube.cpp -o topic1\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n#include <map>\n#include <random>\n#include <string>\n#include <vector>\n\nconst double R = 8.314462618;\nstruct Liq { double A, B, C, rho, M, vol; };\nstd::map<std::string, Liq> L = {\n    {\"water\", {8.07131, 1730.63, 233.426, 997.0, 18.015, 12.7}},\n    {\"ethanol\", {8.20417, 1642.89, 230.300, 789.0, 46.07, 2 * 16.5 + 6 * 1.98 + 5.48}},\n    {\"acetone\", {7.02447, 1161.0, 224.0, 784.0, 58.08, 3 * 16.5 + 6 * 1.98 + 5.48}}};\nconst double VAIR = 20.1;\n\ndouble psat(const std::string& n, double TC) { const Liq& q = L[n]; return std::pow(10.0, q.A - q.B / (q.C + TC)) * 133.322; }\ndouble fuller(const std::string& n, double TK, double Patm = 1.0) {\n    double Ma = L[n].M, Mb = 28.97, den = std::pow(std::cbrt(L[n].vol) + std::cbrt(VAIR), 2);\n    return 1.011e-3 * std::pow(TK, 1.75) * std::sqrt(1 / Ma + 1 / Mb) / (Patm * den) * 1e-4;\n}\ndouble ylm(double yA1, double yA2) { double b1 = 1 - yA1, b2 = 1 - yA2; return std::fabs(b2 - b1) > 1e-12 ? (b2 - b1) / std::log(b2 / b1) : b1; }\ndouble stefanFlux(double c, double D, double Lz, double y1, double y2) { return c * D / Lz * std::log((1 - y2) / (1 - y1)); }\ndouble profile(double z, double Lz, double y1, double y2) { return 1 - (1 - y1) * std::pow((1 - y2) / (1 - y1), z / Lz); }\n\nint main() {\n    double P = 101325.0, TC = 25.0, T = TC + 273.15, c = P / (R * T), Lz = 0.10;\n    std::printf(\"Stefan tube, L = %.0f cm, %.1f C, 1 atm, c = %.3f mol/m^3\\n\", Lz * 100, TC, c);\n    std::printf(\" liquid    p_sat(kPa)  y_A1    D(cm^2/s)  y_B,lm   N_A (mol/m^2 s)  Stefan/Fick\\n\");\n    for (std::string n : {\"water\", \"ethanol\", \"acetone\"}) {\n        double y1 = psat(n, TC) / P, D = fuller(n, T), N = stefanFlux(c, D, Lz, y1, 0.0), Nf = c * D * y1 / Lz;\n        std::printf(\" %-8s %9.2f  %6.4f  %8.4f  %7.4f  %14.4e  %9.4f\\n\", n.c_str(), psat(n, TC) / 1e3, y1, D * 1e4, ylm(y1, 0), N, N / Nf);\n    }\n    double y1 = psat(\"acetone\", TC) / P, D = fuller(\"acetone\", T);\n    double N1 = stefanFlux(c, D, Lz, y1, 0.0), N2 = c * D * y1 / (Lz * ylm(y1, 0.0));\n    std::printf(\"\\nlog form %.6e vs log-mean form %.6e\\n\", N1, N2);\n    double mean = 0; int n = 1000;\n    for (int i = 0; i < n; ++i) mean += 0.5 * ((1 - profile(i * Lz / n, Lz, y1, 0)) + (1 - profile((i + 1) * Lz / n, Lz, y1, 0))) / n;\n    std::printf(\"path-averaged y_B = %.6f equals y_B,lm = %.6f\\n\", mean, ylm(y1, 0.0));\n    double delta = 2e-3, kc = P * D / (delta * ylm(y1, 0.0) * P);\n    std::printf(\"film model (delta = 2 mm): k_c = P D/(delta p_B,lm) = %.3f cm/s\\n\", kc * 100);\n\n    // pseudo-steady Arnold cell: synthetic experiment and back-calculation of D\n    double rhoL = L[\"water\"].rho, MA = L[\"water\"].M;\n    y1 = psat(\"water\", TC) / P;\n    double Dt = fuller(\"water\", T), z0 = 0.02;\n    double K = 2 * c * Dt * MA * 1e-3 * y1 / (rhoL * ylm(y1, 0.0));\n    std::mt19937 gen(3); std::normal_distribution<double> noise(0.0, 2e-5);\n    double sxy = 0, sxx = 0, zlast = 0;\n    for (int d : {1, 2, 4, 6, 8, 10, 14}) {\n        double t = d * 86400.0, z = std::sqrt(z0 * z0 + K * t) + noise(gen);\n        sxy += t * (z * z - z0 * z0); sxx += t * t; zlast = z;\n    }\n    double Dfit = sxy / sxx * rhoL * ylm(y1, 0.0) / (2 * c * MA * 1e-3 * y1);\n    std::printf(\"\\nArnold cell (water, z0 = 2 cm): level after 14 days z = %.3f cm\\n\", zlast * 100);\n    std::printf(\"D_true = %.4f cm^2/s, D from (z^2 - z0^2) vs t fit = %.4f cm^2/s\\n\", Dt * 1e4, Dfit * 1e4);\n}\n",
  },
  topic2: {
    title: "Moving Boundaries: Si Oxidation & Carbon Burnout",
    python: "# Week 10 - Topic 2: Pseudo-Steady Moving Boundaries: Si Oxidation and Carbon-Particle Burnout\n# Lecture (Part 1):\n#   * diffusion-controlled Si oxidation (O2 = A through SiO2 = B, c_A = 0 at the Si interface):\n#       N_Az = D c_As/delta(t);  (rho_B/M_B) d(delta)/dt = N_Az\n#       -> delta(t) = (2 M_B D c_As t / rho_B)^(1/2)          (parabolic law)\n#     with a finite interface reaction N_Az = k_s c_Ai added in series (linear-parabolic form):\n#       delta^2 + (2D/k_s) delta = (2 M_B D c_As/rho_B) t\n#   * carbon sphere burning in still air: 3C + 2.5 O2 -> 2 CO2 + CO  (A = O2)\n#       sum N = -0.2 N_A  ->  N_Ar = -(c D/(1 + 0.2 y_A)) dy_A/dr,   r^2 N_Ar = const\n#       W_O2 = -4 pi R (c D/0.2) ln(1.042)      (y_A = 0 at r = R, 0.21 at infinity)\n#       W_C = (3/2.5)|W_O2| = 12 pi R (c D/0.5) ln(1.042)\n#       t_f = (rho_C/M_C)(R0^2 - Rf^2) / (12 c D ln 1.042)\n#   * single heterogeneous reaction C + O2 -> CO2 with surface rate N_A = -k_s c_As:\n#       W_O2 = -4 pi R c D y_inf / (1 + D/(k_s R))\n# Parameter values below are illustrative (labelled where chosen).\n\nimport math\n\nR = 8.314462618\n\n# ---------- Si oxidation ----------\nM_SiO2, rho_SiO2 = 60.08e-3, 2270.0      # kg/mol, kg/m^3\nc_s = 5.2e16 * 1e6 / 6.02214076e23       # O2 solubility in SiO2 (~5.2e16 cm^-3, dry O2, 1 atm) -> mol/m^3\nD_ox = 3.4e-13                            # m^2/s, illustrative effective value near 1000 degC\n\n\ndef delta_parabolic(t):\n    return math.sqrt(2 * M_SiO2 * D_ox * c_s * t / rho_SiO2)\n\n\ndef delta_linear_parabolic(t, ks):\n    A = 2 * D_ox / ks\n    Bp = 2 * M_SiO2 * D_ox * c_s / rho_SiO2\n    return 0.5 * (-A + math.sqrt(A * A + 4 * Bp * t))\n\n\ndef delta_numeric(t_end, ks=None, n=200000):\n    \"\"\"Integrate (rho/M) d(delta)/dt = N with series resistances (pseudo-steady).\"\"\"\n    d, dt = 1e-10, t_end / n\n    for _ in range(n):\n        res = d / D_ox + (1 / ks if ks else 0.0)\n        N = c_s / res\n        d += M_SiO2 / rho_SiO2 * N * dt\n    return d\n\n# ---------- carbon particle ----------\ndef burnout(R0, Rf, T, P=101325.0, D=2.0e-4, rho_C=2000.0, M_C=0.012):\n    c = P / (R * T)\n    return (rho_C / M_C) * (R0 ** 2 - Rf ** 2) / (12 * c * D * math.log(1.042))\n\n\ndef W_O2_hetero(Rp, T, ks, D=2.0e-4, P=101325.0, yinf=0.21):\n    c = P / (R * T)\n    return -4 * math.pi * Rp * c * D * yinf / (1 + D / (ks * Rp))\n\n\nif __name__ == \"__main__\":\n    print(f\"c_As = {c_s:.4e} mol/m^3\")\n    print(\"  t (h)   parabolic (um)   linear-parabolic ks=1e-5 m/s (um)   numeric (um)\")\n    for h in (1, 2, 4, 8, 16):\n        t = h * 3600\n        print(f\"{h:6d}   {delta_parabolic(t)*1e6:12.4f}   {delta_linear_parabolic(t,1e-5)*1e6:22.4f}   \"\n              f\"{delta_numeric(t,1e-5,40000)*1e6:16.4f}\")\n\n    print(\"\\nCarbon sphere, T = 1200 K, D = 2.0e-4 m^2/s (illustrative), rho_C = 2000 kg/m^3\")\n    print(f\"  ln(1.042)/0.2 = {math.log(1.042)/0.2:.5f} vs 0.21 (no bulk-flow correction)\")\n    for R0_um in (10, 50, 100):\n        print(f\"  R0 = {R0_um:4d} um -> burnout time {burnout(R0_um*1e-6, 0.0, 1200.0):.4f} s\")\n    print(\"  burnout time scales as R0^2: 100 um vs 10 um ->\",\n          round(burnout(100e-6, 0, 1200) / burnout(10e-6, 0, 1200), 1))\n\n    print(\"\\nSingle heterogeneous reaction C + O2 -> CO2, R = 50 um, T = 1200 K\")\n    Rp = 50e-6\n    Wd = W_O2_hetero(Rp, 1200.0, 1e9)\n    for ks in (0.1, 1.0, 10.0, 100.0):\n        W = W_O2_hetero(Rp, 1200.0, ks)\n        print(f\"  k_s = {ks:6.1f} m/s, Da = k_s R/D = {ks*Rp/2e-4:7.3f}: W_O2 = {W:.4e} mol/s ({W/Wd*100:5.1f}% of diffusion limit)\")\n",
    matlab: "% Week 10 - Topic 2: Pseudo-Steady Moving Boundaries: Si Oxidation and Carbon-Particle Burnout\n% Lecture (Part 1):\n%   * diffusion-controlled Si oxidation (O2 = A through SiO2 = B, c_A = 0 at the Si interface):\n%       N_Az = D c_As/delta(t);  (rho_B/M_B) d(delta)/dt = N_Az\n%       -> delta(t) = (2 M_B D c_As t / rho_B)^(1/2)          (parabolic law)\n%     with a finite interface reaction N_Az = k_s c_Ai added in series (linear-parabolic form):\n%       delta^2 + (2D/k_s) delta = (2 M_B D c_As/rho_B) t\n%   * carbon sphere burning in still air: 3C + 2.5 O2 -> 2 CO2 + CO  (A = O2)\n%       sum N = -0.2 N_A  ->  N_Ar = -(c D/(1 + 0.2 y_A)) dy_A/dr,   r^2 N_Ar = const\n%       W_O2 = -4 pi R (c D/0.2) ln(1.042)      (y_A = 0 at r = R, 0.21 at infinity)\n%       W_C = (3/2.5)|W_O2| = 12 pi R (c D/0.5) ln(1.042)\n%       t_f = (rho_C/M_C)(R0^2 - Rf^2) / (12 c D ln 1.042)\n%   * single heterogeneous reaction C + O2 -> CO2 with surface rate N_A = -k_s c_As:\n%       W_O2 = -4 pi R c D y_inf / (1 + D/(k_s R))\n% Parameter values below are illustrative (labelled where chosen).\nfunction week10_topic2_moving_boundary()\n    R = 8.314462618; M = 60.08e-3; rho = 2270; cs = 5.2e16*1e6/6.02214076e23; Dox = 3.4e-13;\n    dpar = @(t) sqrt(2*M*Dox*cs*t/rho);\n    dlp = @(t, ks) 0.5*(-2*Dox/ks + sqrt((2*Dox/ks)^2 + 4*(2*M*Dox*cs/rho)*t));\n    fprintf('c_As = %.4e mol/m^3\\n', cs);\n    fprintf('  t (h)   parabolic (um)   linear-parabolic ks=1e-5 m/s (um)   numeric (um)\\n');\n    for h = [1 2 4 8 16]\n        t = h*3600; n = 40000; dt = t/n; d = 1e-10;\n        for i = 1:n, d = d + M/rho*cs/(d/Dox + 1/1e-5)*dt; end\n        fprintf('%6d   %12.4f   %22.4f   %16.4f\\n', h, dpar(t)*1e6, dlp(t, 1e-5)*1e6, d*1e6);\n    end\n    burn = @(R0, T) (2000/0.012)*R0^2/(12*(101325/(R*T))*2e-4*log(1.042));\n    fprintf('\\nCarbon sphere, T = 1200 K, D = 2.0e-4 m^2/s (illustrative), rho_C = 2000 kg/m^3\\n');\n    fprintf('  ln(1.042)/0.2 = %.5f vs 0.21 (no bulk-flow correction)\\n', log(1.042)/0.2);\n    for r = [10 50 100], fprintf('  R0 = %4d um -> burnout time %.4f s\\n', r, burn(r*1e-6, 1200)); end\n    fprintf('  burnout time scales as R0^2: 100 um vs 10 um -> %.1f\\n', burn(100e-6,1200)/burn(10e-6,1200));\n    W = @(Rp, T, ks) -4*pi*Rp*(101325/(R*T))*2e-4*0.21/(1 + 2e-4/(ks*Rp));\n    fprintf('\\nSingle heterogeneous reaction C + O2 -> CO2, R = 50 um, T = 1200 K\\n');\n    Rp = 50e-6; Wd = W(Rp, 1200, 1e9);\n    for ks = [0.1 1 10 100]\n        w = W(Rp, 1200, ks);\n        fprintf('  k_s = %6.1f m/s, Da = k_s R/D = %7.3f: W_O2 = %.4e mol/s (%5.1f%% of diffusion limit)\\n', ks, ks*Rp/2e-4, w, w/Wd*100);\n    end\nend\n",
    julia: "# Week 10 - Topic 2: Pseudo-Steady Moving Boundaries: Si Oxidation and Carbon-Particle Burnout\n# Lecture (Part 1):\n#   * diffusion-controlled Si oxidation (O2 = A through SiO2 = B, c_A = 0 at the Si interface):\n#       N_Az = D c_As/delta(t);  (rho_B/M_B) d(delta)/dt = N_Az\n#       -> delta(t) = (2 M_B D c_As t / rho_B)^(1/2)          (parabolic law)\n#     with a finite interface reaction N_Az = k_s c_Ai added in series (linear-parabolic form):\n#       delta^2 + (2D/k_s) delta = (2 M_B D c_As/rho_B) t\n#   * carbon sphere burning in still air: 3C + 2.5 O2 -> 2 CO2 + CO  (A = O2)\n#       sum N = -0.2 N_A  ->  N_Ar = -(c D/(1 + 0.2 y_A)) dy_A/dr,   r^2 N_Ar = const\n#       W_O2 = -4 pi R (c D/0.2) ln(1.042)      (y_A = 0 at r = R, 0.21 at infinity)\n#       W_C = (3/2.5)|W_O2| = 12 pi R (c D/0.5) ln(1.042)\n#       t_f = (rho_C/M_C)(R0^2 - Rf^2) / (12 c D ln 1.042)\n#   * single heterogeneous reaction C + O2 -> CO2 with surface rate N_A = -k_s c_As:\n#       W_O2 = -4 pi R c D y_inf / (1 + D/(k_s R))\n# Parameter values below are illustrative (labelled where chosen).\nusing Printf\n\nconst R = 8.314462618\nconst M_SiO2, rho_SiO2 = 60.08e-3, 2270.0\nconst c_s = 5.2e16 * 1e6 / 6.02214076e23\nconst D_ox = 3.4e-13\n\ndelta_parabolic(t) = sqrt(2 * M_SiO2 * D_ox * c_s * t / rho_SiO2)\nfunction delta_linear_parabolic(t, ks)\n    A = 2 * D_ox / ks; Bp = 2 * M_SiO2 * D_ox * c_s / rho_SiO2\n    return 0.5 * (-A + sqrt(A^2 + 4 * Bp * t))\nend\nfunction delta_numeric(tEnd, ks, n)\n    d, dt = 1e-10, tEnd / n\n    for _ in 1:n\n        d += M_SiO2 / rho_SiO2 * c_s / (d / D_ox + 1 / ks) * dt\n    end\n    return d\nend\nburnout(R0, Rf, T; P = 101325.0, D = 2.0e-4, rhoC = 2000.0, MC = 0.012) =\n    (rhoC / MC) * (R0^2 - Rf^2) / (12 * (P / (R * T)) * D * log(1.042))\nW_O2_hetero(Rp, T, ks; D = 2.0e-4, P = 101325.0, yinf = 0.21) =\n    -4pi * Rp * (P / (R * T)) * D * yinf / (1 + D / (ks * Rp))\n\n@printf(\"c_As = %.4e mol/m^3\\n\", c_s)\nprintln(\"  t (h)   parabolic (um)   linear-parabolic ks=1e-5 m/s (um)   numeric (um)\")\nfor h in (1, 2, 4, 8, 16)\n    t = h * 3600.0\n    @printf(\"%6d   %12.4f   %22.4f   %16.4f\\n\", h, delta_parabolic(t) * 1e6, delta_linear_parabolic(t, 1e-5) * 1e6, delta_numeric(t, 1e-5, 40000) * 1e6)\nend\nprintln(\"\\nCarbon sphere, T = 1200 K, D = 2.0e-4 m^2/s (illustrative), rho_C = 2000 kg/m^3\")\n@printf(\"  ln(1.042)/0.2 = %.5f vs 0.21 (no bulk-flow correction)\\n\", log(1.042) / 0.2)\nfor r in (10, 50, 100)\n    @printf(\"  R0 = %4d um -> burnout time %.4f s\\n\", r, burnout(r * 1e-6, 0.0, 1200.0))\nend\n@printf(\"  burnout time scales as R0^2: 100 um vs 10 um -> %.1f\\n\", burnout(100e-6, 0, 1200) / burnout(10e-6, 0, 1200))\nprintln(\"\\nSingle heterogeneous reaction C + O2 -> CO2, R = 50 um, T = 1200 K\")\nRp = 50e-6; Wd = W_O2_hetero(Rp, 1200.0, 1e9)\nfor ks in (0.1, 1.0, 10.0, 100.0)\n    W = W_O2_hetero(Rp, 1200.0, ks)\n    @printf(\"  k_s = %6.1f m/s, Da = k_s R/D = %7.3f: W_O2 = %.4e mol/s (%5.1f%% of diffusion limit)\\n\", ks, ks * Rp / 2e-4, W, W / Wd * 100)\nend\n",
    cpp: "// Week 10 - Topic 2: Pseudo-Steady Moving Boundaries: Si Oxidation and Carbon-Particle Burnout\n// Lecture (Part 1):\n//   * diffusion-controlled Si oxidation (O2 = A through SiO2 = B, c_A = 0 at the Si interface):\n//       N_Az = D c_As/delta(t);  (rho_B/M_B) d(delta)/dt = N_Az\n//       -> delta(t) = (2 M_B D c_As t / rho_B)^(1/2)          (parabolic law)\n//     with a finite interface reaction N_Az = k_s c_Ai added in series (linear-parabolic form):\n//       delta^2 + (2D/k_s) delta = (2 M_B D c_As/rho_B) t\n//   * carbon sphere burning in still air: 3C + 2.5 O2 -> 2 CO2 + CO  (A = O2)\n//       sum N = -0.2 N_A  ->  N_Ar = -(c D/(1 + 0.2 y_A)) dy_A/dr,   r^2 N_Ar = const\n//       W_O2 = -4 pi R (c D/0.2) ln(1.042)      (y_A = 0 at r = R, 0.21 at infinity)\n//       W_C = (3/2.5)|W_O2| = 12 pi R (c D/0.5) ln(1.042)\n//       t_f = (rho_C/M_C)(R0^2 - Rf^2) / (12 c D ln 1.042)\n//   * single heterogeneous reaction C + O2 -> CO2 with surface rate N_A = -k_s c_As:\n//       W_O2 = -4 pi R c D y_inf / (1 + D/(k_s R))\n// Parameter values below are illustrative (labelled where chosen).\n\n// Build: g++ -O2 -std=c++17 week10_topic2_moving_boundary.cpp -o topic2\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n\nconst double R = 8.314462618, PI = 3.14159265358979323846;\nconst double M_SiO2 = 60.08e-3, rho_SiO2 = 2270.0;\nconst double c_s = 5.2e16 * 1e6 / 6.02214076e23;   // mol/m^3\nconst double D_ox = 3.4e-13;                         // m^2/s, illustrative\n\ndouble deltaParabolic(double t) { return std::sqrt(2 * M_SiO2 * D_ox * c_s * t / rho_SiO2); }\ndouble deltaLinPar(double t, double ks) {\n    double A = 2 * D_ox / ks, Bp = 2 * M_SiO2 * D_ox * c_s / rho_SiO2;\n    return 0.5 * (-A + std::sqrt(A * A + 4 * Bp * t));\n}\ndouble deltaNumeric(double tEnd, double ks, int n) {\n    double d = 1e-10, dt = tEnd / n;\n    for (int i = 0; i < n; ++i) { double res = d / D_ox + (ks > 0 ? 1 / ks : 0.0); d += M_SiO2 / rho_SiO2 * (c_s / res) * dt; }\n    return d;\n}\ndouble burnout(double R0, double Rf, double T, double P = 101325.0, double D = 2.0e-4, double rhoC = 2000.0, double MC = 0.012) {\n    double c = P / (R * T);\n    return (rhoC / MC) * (R0 * R0 - Rf * Rf) / (12 * c * D * std::log(1.042));\n}\ndouble WO2hetero(double Rp, double T, double ks, double D = 2.0e-4, double P = 101325.0, double yinf = 0.21) {\n    double c = P / (R * T);\n    return -4 * PI * Rp * c * D * yinf / (1 + D / (ks * Rp));\n}\n\nint main() {\n    std::printf(\"c_As = %.4e mol/m^3\\n\", c_s);\n    std::printf(\"  t (h)   parabolic (um)   linear-parabolic ks=1e-5 m/s (um)   numeric (um)\\n\");\n    for (int h : {1, 2, 4, 8, 16}) {\n        double t = h * 3600.0;\n        std::printf(\"%6d   %12.4f   %22.4f   %16.4f\\n\", h, deltaParabolic(t) * 1e6, deltaLinPar(t, 1e-5) * 1e6, deltaNumeric(t, 1e-5, 40000) * 1e6);\n    }\n    std::printf(\"\\nCarbon sphere, T = 1200 K, D = 2.0e-4 m^2/s (illustrative), rho_C = 2000 kg/m^3\\n\");\n    std::printf(\"  ln(1.042)/0.2 = %.5f vs 0.21 (no bulk-flow correction)\\n\", std::log(1.042) / 0.2);\n    for (int r : {10, 50, 100}) std::printf(\"  R0 = %4d um -> burnout time %.4f s\\n\", r, burnout(r * 1e-6, 0.0, 1200.0));\n    std::printf(\"  burnout time scales as R0^2: 100 um vs 10 um -> %.1f\\n\", burnout(100e-6, 0, 1200) / burnout(10e-6, 0, 1200));\n    std::printf(\"\\nSingle heterogeneous reaction C + O2 -> CO2, R = 50 um, T = 1200 K\\n\");\n    double Rp = 50e-6, Wd = WO2hetero(Rp, 1200.0, 1e9);\n    for (double ks : {0.1, 1.0, 10.0, 100.0}) {\n        double W = WO2hetero(Rp, 1200.0, ks);\n        std::printf(\"  k_s = %6.1f m/s, Da = k_s R/D = %7.3f: W_O2 = %.4e mol/s (%5.1f%% of diffusion limit)\\n\", ks, ks * Rp / 2e-4, W, W / Wd * 100);\n    }\n}\n",
  },
  topic3: {
    title: "Reaction in a Liquid Film (Hatta) & Grove CVD Model",
    python: "# Week 10 - Topic 3: Diffusion with Reaction: Liquid Film (Hatta) and CVD Growth (Grove Model)\n# Lecture (Part 1):\n#   * gas A absorbed into liquid B with first-order homogeneous reaction R_A = -k1 c_A:\n#       D_AB d^2c_A/dz^2 - k1 c_A = 0,  c_A(0) = c_A0,  c_A(delta) = 0\n#       c_A(z) = c_A0 [cosh(phi z/delta) - sinh(phi z/delta)/tanh(phi)],  phi = delta sqrt(k1/D_AB)\n#       N_Az|0 = (D_AB c_A0/delta) * phi/tanh(phi)\n#     phi is the Hatta number Ha; E = Ha/tanh(Ha) is the enhancement over physical absorption\n#     (the lecture labels this flux ratio \"Hatta number\").\n#     large k1: N_Az -> sqrt(D_AB k1) c_A0, so k_c ~ D^(1/2) (vs k_c ~ D for the film model)\n#   * CVD growth (Grove): gas-phase transfer F1 = h_g (C_g - C_s), surface reaction F2 = k_s C_s\n#       steady state: F1 = F2 -> growth rate = (h_g k_s/(h_g + k_s)) C_g / rho\n#       low T: k_s = k_s0 exp(-Ea/kT) << h_g -> reaction limited (Ea ~ 1.9 eV)\n#       high T: k_s >> h_g ~ T^n (n = 1.5-2) -> mass-transport limited\n# CVD parameter values are illustrative.\n\nimport math\n\nKB_EV = 8.617333262e-5   # eV/K\n\n\ndef film_profile(zeta, Ha):\n    return math.cosh(Ha * zeta) - math.sinh(Ha * zeta) / math.tanh(Ha)\n\n\ndef enhancement(Ha):\n    return Ha / math.tanh(Ha)\n\n\ndef film_fdm(Ha, n=400):\n    \"\"\"Solve u'' = Ha^2 u on [0,1], u(0)=1, u(1)=0 by finite differences (Thomas).\"\"\"\n    h = 1.0 / n\n    a = [0.0] * (n + 1); b = [1.0] * (n + 1); c = [0.0] * (n + 1); d = [0.0] * (n + 1)\n    d[0] = 1.0\n    for i in range(1, n):\n        a[i], b[i], c[i] = 1.0, -(2 + (Ha * h) ** 2), 1.0\n    for i in range(1, n + 1):\n        m = a[i] / b[i - 1]; b[i] -= m * c[i - 1]; d[i] -= m * d[i - 1]\n    u = [0.0] * (n + 1)\n    u[n] = d[n] / b[n]\n    for i in range(n - 1, -1, -1):\n        u[i] = (d[i] - c[i] * u[i + 1]) / b[i]\n    # second-order one-sided derivative at z = 0\n    dudz = (-3 * u[0] + 4 * u[1] - u[2]) / (2 * h)\n    return u, -dudz\n\n\ndef grove_rate(T, ks0=1.0e9, Ea=1.9, hg0=0.05, n=1.75, Cg=1.0, rho=1.0):\n    ks = ks0 * math.exp(-Ea / (KB_EV * T))\n    hg = hg0 * (T / 1000.0) ** n\n    return hg * ks / (hg + ks) * Cg / rho, ks, hg\n\n\nif __name__ == \"__main__\":\n    print(\" Ha      E = Ha/tanh(Ha)   E from FDM    large-Ha limit (=Ha)\")\n    for Ha in (0.1, 0.5, 1.0, 2.0, 5.0, 10.0):\n        u, E_num = film_fdm(Ha)\n        print(f\"{Ha:5.1f}   {enhancement(Ha):12.5f}   {E_num:10.5f}   {Ha:10.3f}\")\n    print(\"profile check Ha = 3, z/delta = 0.5:\", round(film_profile(0.5, 3.0), 5),\n          \"FDM:\", round(film_fdm(3.0)[0][200], 5))\n\n    # k_c scaling: film model vs penetration (reaction-dominated) model\n    k1, delta = 100.0, 1e-4\n    print(\"\\n D (m^2/s)   film k_c = D/delta   reaction k_c = sqrt(D k1)\")\n    for D in (5e-10, 1e-9, 2e-9, 4e-9):\n        print(f\" {D:.1e}    {D/delta:.3e}         {math.sqrt(D*k1):.3e}\")\n    print(\" doubling D: film x2, reaction x\", round(math.sqrt(2), 3))\n\n    print(\"\\nGrove model (illustrative constants): rate ~ h_g k_s/(h_g + k_s)\")\n    print(\"  T (K)   k_s        h_g        rate       regime\")\n    for T in (700, 800, 900, 1000, 1100, 1200, 1300):\n        r, ks, hg = grove_rate(T)\n        reg = \"reaction-limited\" if ks < 0.1 * hg else (\"transport-limited\" if ks > 10 * hg else \"mixed\")\n        print(f\"  {T:5d}  {ks:9.3e}  {hg:9.3e}  {r:9.3e}  {reg}\")\n    T1, T2 = 700.0, 750.0\n    Ea_fit = -KB_EV * math.log(grove_rate(T2)[0] / grove_rate(T1)[0]) / (1 / T2 - 1 / T1)\n    print(f\"  apparent Ea from the low-T slope = {Ea_fit:.3f} eV (input 1.9 eV)\")\n",
    matlab: "% Week 10 - Topic 3: Diffusion with Reaction: Liquid Film (Hatta) and CVD Growth (Grove Model)\n% Lecture (Part 1):\n%   * gas A absorbed into liquid B with first-order homogeneous reaction R_A = -k1 c_A:\n%       D_AB d^2c_A/dz^2 - k1 c_A = 0,  c_A(0) = c_A0,  c_A(delta) = 0\n%       c_A(z) = c_A0 [cosh(phi z/delta) - sinh(phi z/delta)/tanh(phi)],  phi = delta sqrt(k1/D_AB)\n%       N_Az|0 = (D_AB c_A0/delta) * phi/tanh(phi)\n%     phi is the Hatta number Ha; E = Ha/tanh(Ha) is the enhancement over physical absorption\n%     (the lecture labels this flux ratio \"Hatta number\").\n%     large k1: N_Az -> sqrt(D_AB k1) c_A0, so k_c ~ D^(1/2) (vs k_c ~ D for the film model)\n%   * CVD growth (Grove): gas-phase transfer F1 = h_g (C_g - C_s), surface reaction F2 = k_s C_s\n%       steady state: F1 = F2 -> growth rate = (h_g k_s/(h_g + k_s)) C_g / rho\n%       low T: k_s = k_s0 exp(-Ea/kT) << h_g -> reaction limited (Ea ~ 1.9 eV)\n%       high T: k_s >> h_g ~ T^n (n = 1.5-2) -> mass-transport limited\n% CVD parameter values are illustrative.\nfunction week10_topic3_reaction_film_cvd()\n    kB = 8.617333262e-5;\n    fprintf(' Ha      E = Ha/tanh(Ha)   E from FDM    large-Ha limit (=Ha)\\n');\n    for Ha = [0.1 0.5 1 2 5 10]\n        [~, E] = filmFDM(Ha, 400);\n        fprintf('%5.1f   %12.5f   %10.5f   %10.3f\\n', Ha, Ha/tanh(Ha), E, Ha);\n    end\n    u = filmFDM(3, 400);\n    fprintf('profile check Ha = 3, z/delta = 0.5: %.5f FDM: %.5f\\n', cosh(1.5) - sinh(1.5)/tanh(3), u(201));\n    k1 = 100; delta = 1e-4;\n    fprintf('\\n D (m^2/s)   film k_c = D/delta   reaction k_c = sqrt(D k1)\\n');\n    for D = [5e-10 1e-9 2e-9 4e-9], fprintf(' %.1e    %.3e         %.3e\\n', D, D/delta, sqrt(D*k1)); end\n    fprintf(' doubling D: film x2, reaction x %.3f\\n', sqrt(2));\n    fprintf('\\nGrove model (illustrative constants): rate ~ h_g k_s/(h_g + k_s)\\n');\n    fprintf('  T (K)   k_s        h_g        rate       regime\\n');\n    grove = @(T) deal(1e9*exp(-1.9./(kB*T)), 0.05*(T/1000).^1.75);\n    for T = 700:100:1300\n        [ks, hg] = grove(T); r = hg*ks/(hg + ks);\n        if ks < 0.1*hg, reg = 'reaction-limited'; elseif ks > 10*hg, reg = 'transport-limited'; else, reg = 'mixed'; end\n        fprintf('  %5d  %9.3e  %9.3e  %9.3e  %s\\n', T, ks, hg, r, reg);\n    end\n    [k1s, h1] = grove(700); [k2s, h2] = grove(750);\n    r1 = h1*k1s/(h1 + k1s); r2 = h2*k2s/(h2 + k2s);\n    fprintf('  apparent Ea from the low-T slope = %.3f eV (input 1.9 eV)\\n', -kB*log(r2/r1)/(1/750 - 1/700));\nend\n\nfunction [u, E] = filmFDM(Ha, n)\n    % u'' = Ha^2 u on [0,1], u(0) = 1, u(1) = 0\n    h = 1/n; m = n - 1;\n    A = spdiags([ones(m,1), -(2 + (Ha*h)^2)*ones(m,1), ones(m,1)], -1:1, m, m);\n    b = zeros(m, 1); b(1) = -1;\n    u = [1; A\\b; 0];\n    E = -(-3*u(1) + 4*u(2) - u(3))/(2*h);\nend\n",
    julia: "# Week 10 - Topic 3: Diffusion with Reaction: Liquid Film (Hatta) and CVD Growth (Grove Model)\n# Lecture (Part 1):\n#   * gas A absorbed into liquid B with first-order homogeneous reaction R_A = -k1 c_A:\n#       D_AB d^2c_A/dz^2 - k1 c_A = 0,  c_A(0) = c_A0,  c_A(delta) = 0\n#       c_A(z) = c_A0 [cosh(phi z/delta) - sinh(phi z/delta)/tanh(phi)],  phi = delta sqrt(k1/D_AB)\n#       N_Az|0 = (D_AB c_A0/delta) * phi/tanh(phi)\n#     phi is the Hatta number Ha; E = Ha/tanh(Ha) is the enhancement over physical absorption\n#     (the lecture labels this flux ratio \"Hatta number\").\n#     large k1: N_Az -> sqrt(D_AB k1) c_A0, so k_c ~ D^(1/2) (vs k_c ~ D for the film model)\n#   * CVD growth (Grove): gas-phase transfer F1 = h_g (C_g - C_s), surface reaction F2 = k_s C_s\n#       steady state: F1 = F2 -> growth rate = (h_g k_s/(h_g + k_s)) C_g / rho\n#       low T: k_s = k_s0 exp(-Ea/kT) << h_g -> reaction limited (Ea ~ 1.9 eV)\n#       high T: k_s >> h_g ~ T^n (n = 1.5-2) -> mass-transport limited\n# CVD parameter values are illustrative.\nusing Printf, LinearAlgebra\n\nconst KB_EV = 8.617333262e-5\n\nfilm_profile(zeta, Ha) = cosh(Ha * zeta) - sinh(Ha * zeta) / tanh(Ha)\nenhancement(Ha) = Ha / tanh(Ha)\n\nfunction film_fdm(Ha, n = 400)\n    h = 1 / n; m = n - 1\n    A = SymTridiagonal(fill(-(2 + (Ha * h)^2), m), ones(m - 1))\n    b = zeros(m); b[1] = -1.0\n    u = [1.0; A \\ b; 0.0]\n    return u, -(-3u[1] + 4u[2] - u[3]) / (2h)\nend\n\nfunction grove_rate(T; ks0 = 1.0e9, Ea = 1.9, hg0 = 0.05, n = 1.75)\n    ks = ks0 * exp(-Ea / (KB_EV * T)); hg = hg0 * (T / 1000)^n\n    return hg * ks / (hg + ks), ks, hg\nend\n\nprintln(\" Ha      E = Ha/tanh(Ha)   E from FDM    large-Ha limit (=Ha)\")\nfor Ha in (0.1, 0.5, 1.0, 2.0, 5.0, 10.0)\n    @printf(\"%5.1f   %12.5f   %10.5f   %10.3f\\n\", Ha, enhancement(Ha), film_fdm(Ha)[2], Ha)\nend\n@printf(\"profile check Ha = 3, z/delta = 0.5: %.5f FDM: %.5f\\n\", film_profile(0.5, 3.0), film_fdm(3.0)[1][201])\nk1, delta = 100.0, 1e-4\nprintln(\"\\n D (m^2/s)   film k_c = D/delta   reaction k_c = sqrt(D k1)\")\nfor D in (5e-10, 1e-9, 2e-9, 4e-9)\n    @printf(\" %.1e    %.3e         %.3e\\n\", D, D / delta, sqrt(D * k1))\nend\n@printf(\" doubling D: film x2, reaction x %.3f\\n\", sqrt(2))\nprintln(\"\\nGrove model (illustrative constants): rate ~ h_g k_s/(h_g + k_s)\")\nprintln(\"  T (K)   k_s        h_g        rate       regime\")\nfor T in 700:100:1300\n    r, ks, hg = grove_rate(T)\n    reg = ks < 0.1hg ? \"reaction-limited\" : (ks > 10hg ? \"transport-limited\" : \"mixed\")\n    @printf(\"  %5d  %9.3e  %9.3e  %9.3e  %s\\n\", T, ks, hg, r, reg)\nend\nT1, T2 = 700.0, 750.0\n@printf(\"  apparent Ea from the low-T slope = %.3f eV (input 1.9 eV)\\n\", -KB_EV * log(grove_rate(T2)[1] / grove_rate(T1)[1]) / (1 / T2 - 1 / T1))\n",
    cpp: "// Week 10 - Topic 3: Diffusion with Reaction: Liquid Film (Hatta) and CVD Growth (Grove Model)\n// Lecture (Part 1):\n//   * gas A absorbed into liquid B with first-order homogeneous reaction R_A = -k1 c_A:\n//       D_AB d^2c_A/dz^2 - k1 c_A = 0,  c_A(0) = c_A0,  c_A(delta) = 0\n//       c_A(z) = c_A0 [cosh(phi z/delta) - sinh(phi z/delta)/tanh(phi)],  phi = delta sqrt(k1/D_AB)\n//       N_Az|0 = (D_AB c_A0/delta) * phi/tanh(phi)\n//     phi is the Hatta number Ha; E = Ha/tanh(Ha) is the enhancement over physical absorption\n//     (the lecture labels this flux ratio \"Hatta number\").\n//     large k1: N_Az -> sqrt(D_AB k1) c_A0, so k_c ~ D^(1/2) (vs k_c ~ D for the film model)\n//   * CVD growth (Grove): gas-phase transfer F1 = h_g (C_g - C_s), surface reaction F2 = k_s C_s\n//       steady state: F1 = F2 -> growth rate = (h_g k_s/(h_g + k_s)) C_g / rho\n//       low T: k_s = k_s0 exp(-Ea/kT) << h_g -> reaction limited (Ea ~ 1.9 eV)\n//       high T: k_s >> h_g ~ T^n (n = 1.5-2) -> mass-transport limited\n// CVD parameter values are illustrative.\n\n// Build: g++ -O2 -std=c++17 week10_topic3_reaction_film_cvd.cpp -o topic3\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n#include <vector>\n\nconst double KB_EV = 8.617333262e-5;\n\ndouble filmProfile(double zeta, double Ha) { return std::cosh(Ha * zeta) - std::sinh(Ha * zeta) / std::tanh(Ha); }\ndouble enhancement(double Ha) { return Ha / std::tanh(Ha); }\n\n// u'' = Ha^2 u on [0,1], u(0) = 1, u(1) = 0 (Thomas algorithm); returns -u'(0)\ndouble filmFDM(double Ha, int n, std::vector<double>& u) {\n    double h = 1.0 / n;\n    std::vector<double> a(n + 1, 0.0), b(n + 1, 1.0), c(n + 1, 0.0), d(n + 1, 0.0);\n    d[0] = 1.0;\n    for (int i = 1; i < n; ++i) { a[i] = 1.0; b[i] = -(2 + Ha * Ha * h * h); c[i] = 1.0; }\n    for (int i = 1; i <= n; ++i) { double m = a[i] / b[i - 1]; b[i] -= m * c[i - 1]; d[i] -= m * d[i - 1]; }\n    u.assign(n + 1, 0.0);\n    u[n] = d[n] / b[n];\n    for (int i = n - 1; i >= 0; --i) u[i] = (d[i] - c[i] * u[i + 1]) / b[i];\n    return -(-3 * u[0] + 4 * u[1] - u[2]) / (2 * h);\n}\n\ndouble groveRate(double T, double& ks, double& hg, double ks0 = 1.0e9, double Ea = 1.9, double hg0 = 0.05, double n = 1.75) {\n    ks = ks0 * std::exp(-Ea / (KB_EV * T));\n    hg = hg0 * std::pow(T / 1000.0, n);\n    return hg * ks / (hg + ks);\n}\n\nint main() {\n    std::vector<double> u;\n    std::printf(\" Ha      E = Ha/tanh(Ha)   E from FDM    large-Ha limit (=Ha)\\n\");\n    for (double Ha : {0.1, 0.5, 1.0, 2.0, 5.0, 10.0})\n        std::printf(\"%5.1f   %12.5f   %10.5f   %10.3f\\n\", Ha, enhancement(Ha), filmFDM(Ha, 400, u), Ha);\n    filmFDM(3.0, 400, u);\n    std::printf(\"profile check Ha = 3, z/delta = 0.5: %.5f FDM: %.5f\\n\", filmProfile(0.5, 3.0), u[200]);\n\n    double k1 = 100.0, delta = 1e-4;\n    std::printf(\"\\n D (m^2/s)   film k_c = D/delta   reaction k_c = sqrt(D k1)\\n\");\n    for (double D : {5e-10, 1e-9, 2e-9, 4e-9}) std::printf(\" %.1e    %.3e         %.3e\\n\", D, D / delta, std::sqrt(D * k1));\n    std::printf(\" doubling D: film x2, reaction x %.3f\\n\", std::sqrt(2.0));\n\n    std::printf(\"\\nGrove model (illustrative constants): rate ~ h_g k_s/(h_g + k_s)\\n\");\n    std::printf(\"  T (K)   k_s        h_g        rate       regime\\n\");\n    for (int T : {700, 800, 900, 1000, 1100, 1200, 1300}) {\n        double ks, hg, r = groveRate(T, ks, hg);\n        const char* reg = ks < 0.1 * hg ? \"reaction-limited\" : (ks > 10 * hg ? \"transport-limited\" : \"mixed\");\n        std::printf(\"  %5d  %9.3e  %9.3e  %9.3e  %s\\n\", T, ks, hg, r, reg);\n    }\n    double ks, hg, T1 = 700, T2 = 750;\n    double r1 = groveRate(T1, ks, hg), r2 = groveRate(T2, ks, hg);\n    std::printf(\"  apparent Ea from the low-T slope = %.3f eV (input 1.9 eV)\\n\", -KB_EV * std::log(r2 / r1) / (1 / T2 - 1 / T1));\n}\n",
  },
  topic4: {
    title: "2D Laplace: Series Solution & TEOS Wafer-Gap FDM",
    python: "# Week 10 - Topic 4: Two-Dimensional Steady Diffusion (Laplace Equation)\n# Lecture (Part 2):\n#   * rectangle 0<x<W, 0<y<H: c = 0 on x=0, x=W, y=0; c = c0 on y=H\n#       c/c0 = sum_{n odd} (4/(n pi)) sin(n pi x/W) sinh(n pi y/W)/sinh(n pi H/W)\n#   * TEOS stagnant gas between two wafers (LPCVD furnace): cylindrical (r, z)\n#       (1/r) d/dr(r dc/dr) + d^2c/dz^2 = 0\n#       c = c_A0 at r = R (open edge), c = 0 at z = 0 (fast surface reaction on the wafer),\n#       dc/dr = 0 at r = 0, dc/dz = 0 at z = L/2 (mid-plane symmetry)\n#     deposition flux on the wafer N(r) = D dc/dz|_{z=0}: the edge receives more than the center.\n#   * extension: finite surface rate D dc/dz = ks c at the wafer, Da = ks L/D.\n#     For a thin gap (L << R) the gap-averaged balance gives a Bessel problem:\n#       c = c_A0 I0(m r)/I0(m R),  m^2 = 2 ks/(D L),  Thiele modulus Phi = m R\n#     centre/edge deposition ratio = 1/I0(Phi): uniform wafers need Phi < ~0.5\n#     (reaction-limited LPCVD), which is why TEOS furnaces can stack wafers closely.\n\nimport math\n\n\ndef rect_series(x, y, W=1.0, H=1.0, nterms=101):\n    s = 0.0\n    for n in range(1, nterms + 1, 2):\n        a = n * math.pi / W\n        # sinh ratio written to avoid overflow for large n\n        ratio = math.exp(a * (y - H)) * (1 - math.exp(-2 * a * y)) / (1 - math.exp(-2 * a * H))\n        s += 4 / (n * math.pi) * math.sin(a * x) * ratio\n    return s\n\n\ndef rect_sor(N=40, W=1.0, H=1.0, omega=1.85, tol=1e-9):\n    h = W / N\n    M = int(round(H / h))\n    c = [[0.0] * (N + 1) for _ in range(M + 1)]\n    for i in range(1, N):\n        c[M][i] = 1.0\n    for it in range(20000):\n        err = 0.0\n        for j in range(1, M):\n            for i in range(1, N):\n                new = 0.25 * (c[j][i - 1] + c[j][i + 1] + c[j - 1][i] + c[j + 1][i])\n                d = omega * (new - c[j][i]); c[j][i] += d; err = max(err, abs(d))\n        if err < tol:\n            return c, it + 1\n    return c, it + 1\n\n\ndef I0(x):\n    # modified Bessel function of the first kind, order 0 (power series)\n    s, term, k = 1.0, 1.0, 1\n    while True:\n        term *= (x / (2 * k)) ** 2\n        s += term\n        if term < 1e-16 * s:\n            return s\n        k += 1\n\n\ndef thin_gap(r, R, Da, L):\n    \"\"\"gap-averaged model: (1/r)(r c')' = (2 ks/(D L)) c -> c = I0(m r)/I0(m R).\"\"\"\n    m = math.sqrt(2 * Da) / L          # Da = ks L / D,  m^2 = 2 ks/(D L)\n    return I0(m * r) / I0(m * R)\n\n\ndef wafer_sor(R=1.0, L=0.1, Da=0.01, Nr=80, Nz=10, omega=1.9, tol=1e-10, maxit=200000):\n    \"\"\"FDM on r in [0,R], z in [0,L/2]; Robin BC D dc/dz = ks c on the wafer (z = 0).\n    Da = ks L/D; Da -> infinity recovers the lecture case c = 0 on the wafer.\"\"\"\n    dr, dz = R / Nr, (L / 2) / Nz\n    c = [[1.0 if i == Nr else 0.0 for i in range(Nr + 1)] for _ in range(Nz + 1)]\n    ar, az = 1 / dr ** 2, 1 / dz ** 2\n    beta = 2 * dz * Da / L\n    for it in range(maxit):\n        err = 0.0\n        for j in range(1, Nz + 1):\n            for i in range(0, Nr):\n                up = c[j + 1][i] if j < Nz else c[j - 1][i]       # symmetry at z = L/2\n                dn = c[j - 1][i]\n                if i == 0:                                        # r = 0 (L'Hopital)\n                    new = (4 * ar * c[j][1] + az * (up + dn)) / (4 * ar + 2 * az)\n                else:\n                    r = i * dr\n                    w = (1 - dr / (2 * r)) * ar; e = (1 + dr / (2 * r)) * ar\n                    new = (w * c[j][i - 1] + e * c[j][i + 1] + az * (up + dn)) / (2 * ar + 2 * az)\n                d = omega * (new - c[j][i]); c[j][i] += d; err = max(err, abs(d))\n        for i in range(0, Nr):                                    # wafer surface node\n            new = (4 * c[1][i] - c[2][i]) / (3 + beta)\n            err = max(err, abs(new - c[0][i])); c[0][i] = new\n        if err < tol:\n            break\n    flux = [Da * c[0][i] for i in range(Nr + 1)]                  # (L/(D c0)) N_wafer\n    return c, flux, it + 1\n\n\nif __name__ == \"__main__\":\n    print(\"Rectangle W = H = 1, c/c0 at (x, y):\")\n    cs, its = rect_sor()\n    for (x, y) in ((0.5, 0.5), (0.25, 0.75), (0.5, 0.9), (0.1, 0.5)):\n        i, j = int(round(x * 40)), int(round(y * 40))\n        print(f\"  ({x:.2f},{y:.2f})  series = {rect_series(x, y):.5f}   SOR(40x40) = {cs[j][i]:.5f}\")\n    print(\"  SOR iterations:\", its, \"   centre value exact = 0.25 by superposition\")\n    print(\"  Gibbs: partial sums at (0.02, 1.0):\",\n          [round(rect_series(0.02, 1.0, nterms=n), 4) for n in (5, 21, 101)])\n\n    print(\"\\nTEOS wafer gap: R = 1, gap L = 0.1, Robin BC with Da = ks L/D\")\n    print(\"  Thiele modulus Phi = R sqrt(2 Da)/L ; centre/edge deposition = 1/I0(Phi)\")\n    print(\"  Da        Phi     FDM centre/edge   thin-gap 1/I0(Phi)   SOR its\")\n    for Da in (1e-4, 1e-3, 1e-2, 5e-2):\n        c, f, its = wafer_sor(Da=Da)\n        Phi = math.sqrt(2 * Da) / 0.1\n        print(f\"  {Da:7.1e}  {Phi:6.3f}   {c[0][0]:.4f}            {thin_gap(0, 1, Da, 0.1):.4f}             {its}\")\n    print(\"  radial profile at Da = 1e-2 (Phi = 1.414):\")\n    c, f, _ = wafer_sor(Da=1e-2)\n    for frac in (0.0, 0.25, 0.5, 0.75, 1.0):\n        i = int(round(frac * 80))\n        print(f\"    r/R = {frac:4.2f}   FDM c_wafer = {c[0][i]:.4f}   thin-gap = {thin_gap(frac, 1, 1e-2, 0.1):.4f}\")\n",
    matlab: "% Week 10 - Topic 4: Two-Dimensional Steady Diffusion (Laplace Equation)\n% Lecture (Part 2):\n%   * rectangle 0<x<W, 0<y<H: c = 0 on x=0, x=W, y=0; c = c0 on y=H\n%       c/c0 = sum_{n odd} (4/(n pi)) sin(n pi x/W) sinh(n pi y/W)/sinh(n pi H/W)\n%   * TEOS stagnant gas between two wafers (LPCVD furnace): cylindrical (r, z)\n%       (1/r) d/dr(r dc/dr) + d^2c/dz^2 = 0\n%       c = c_A0 at r = R (open edge), c = 0 at z = 0 (fast surface reaction on the wafer),\n%       dc/dr = 0 at r = 0, dc/dz = 0 at z = L/2 (mid-plane symmetry)\n%     deposition flux on the wafer N(r) = D dc/dz|_{z=0}: the edge receives more than the center.\n%   * extension: finite surface rate D dc/dz = ks c at the wafer, Da = ks L/D.\n%     For a thin gap (L << R) the gap-averaged balance gives a Bessel problem:\n%       c = c_A0 I0(m r)/I0(m R),  m^2 = 2 ks/(D L),  Thiele modulus Phi = m R\n%     centre/edge deposition ratio = 1/I0(Phi): uniform wafers need Phi < ~0.5\n%     (reaction-limited LPCVD), which is why TEOS furnaces can stack wafers closely.\nfunction week10_topic4_laplace_2d()\n    fprintf('Rectangle W = H = 1, c/c0 at (x, y):\\n');\n    [cs, its] = rectSOR(40, 1.85, 1e-9);\n    pts = [0.5 0.5; 0.25 0.75; 0.5 0.9; 0.1 0.5];\n    for k = 1:4\n        i = round(pts(k,1)*40) + 1; j = round(pts(k,2)*40) + 1;\n        fprintf('  (%.2f,%.2f)  series = %.5f   SOR(40x40) = %.5f\\n', pts(k,1), pts(k,2), rectSeries(pts(k,1), pts(k,2), 101), cs(j,i));\n    end\n    fprintf('  SOR iterations: %d    centre value exact = 0.25 by superposition\\n', its);\n    fprintf('  Gibbs: partial sums at (0.02, 1.0): [%.4f, %.4f, %.4f]\\n', rectSeries(0.02,1,5), rectSeries(0.02,1,21), rectSeries(0.02,1,101));\n\n    fprintf('\\nTEOS wafer gap: R = 1, gap L = 0.1, Robin BC with Da = ks L/D\\n');\n    fprintf('  Thiele modulus Phi = R sqrt(2 Da)/L ; centre/edge deposition = 1/I0(Phi)\\n');\n    fprintf('  Da        Phi     FDM centre/edge   thin-gap 1/I0(Phi)   SOR its\\n');\n    for Da = [1e-4 1e-3 1e-2 5e-2]\n        [c, k] = waferSOR(Da);\n        Phi = sqrt(2*Da)/0.1;\n        fprintf('  %7.1e  %6.3f   %.4f            %.4f             %d\\n', Da, Phi, c(1,1), 1/besseli(0, Phi), k);\n    end\n    fprintf('  radial profile at Da = 1e-2 (Phi = 1.414):\\n');\n    c = waferSOR(1e-2); m = sqrt(2*1e-2)/0.1;\n    for f = [0 0.25 0.5 0.75 1]\n        fprintf('    r/R = %4.2f   FDM c_wafer = %.4f   thin-gap = %.4f\\n', f, c(1, round(f*80)+1), besseli(0, m*f)/besseli(0, m));\n    end\nend\n\nfunction s = rectSeries(x, y, nterms)\n    s = 0;\n    for n = 1:2:nterms\n        a = n*pi;\n        s = s + 4/(n*pi)*sin(a*x)*exp(a*(y - 1))*(1 - exp(-2*a*y))/(1 - exp(-2*a));\n    end\nend\n\nfunction [c, it] = rectSOR(N, omega, tol)\n    c = zeros(N+1); c(N+1, 2:N) = 1;\n    for it = 1:20000\n        err = 0;\n        for j = 2:N\n            for i = 2:N\n                d = omega*(0.25*(c(j,i-1) + c(j,i+1) + c(j-1,i) + c(j+1,i)) - c(j,i));\n                c(j,i) = c(j,i) + d; err = max(err, abs(d));\n            end\n        end\n        if err < tol, return; end\n    end\nend\n\nfunction [c, it] = waferSOR(Da)\n    % rows j = 1..Nz+1 (z = 0..L/2), columns i = 1..Nr+1 (r = 0..R); wafer at row 1\n    R = 1; L = 0.1; Nr = 80; Nz = 10; omega = 1.9; tol = 1e-10;\n    dr = R/Nr; dz = (L/2)/Nz; ar = 1/dr^2; az = 1/dz^2; beta = 2*dz*Da/L;\n    c = zeros(Nz+1, Nr+1); c(:, Nr+1) = 1;\n    for it = 1:200000\n        err = 0;\n        for j = 2:Nz+1\n            for i = 1:Nr\n                if j < Nz+1, up = c(j+1,i); else, up = c(j-1,i); end\n                dn = c(j-1,i);\n                if i == 1\n                    nw = (4*ar*c(j,2) + az*(up + dn))/(4*ar + 2*az);\n                else\n                    r = (i-1)*dr; w = (1 - dr/(2*r))*ar; e = (1 + dr/(2*r))*ar;\n                    nw = (w*c(j,i-1) + e*c(j,i+1) + az*(up + dn))/(2*ar + 2*az);\n                end\n                d = omega*(nw - c(j,i)); c(j,i) = c(j,i) + d; err = max(err, abs(d));\n            end\n        end\n        for i = 1:Nr\n            nw = (4*c(2,i) - c(3,i))/(3 + beta); err = max(err, abs(nw - c(1,i))); c(1,i) = nw;\n        end\n        if err < tol, return; end\n    end\nend\n",
    julia: "# Week 10 - Topic 4: Two-Dimensional Steady Diffusion (Laplace Equation)\n# Lecture (Part 2):\n#   * rectangle 0<x<W, 0<y<H: c = 0 on x=0, x=W, y=0; c = c0 on y=H\n#       c/c0 = sum_{n odd} (4/(n pi)) sin(n pi x/W) sinh(n pi y/W)/sinh(n pi H/W)\n#   * TEOS stagnant gas between two wafers (LPCVD furnace): cylindrical (r, z)\n#       (1/r) d/dr(r dc/dr) + d^2c/dz^2 = 0\n#       c = c_A0 at r = R (open edge), c = 0 at z = 0 (fast surface reaction on the wafer),\n#       dc/dr = 0 at r = 0, dc/dz = 0 at z = L/2 (mid-plane symmetry)\n#     deposition flux on the wafer N(r) = D dc/dz|_{z=0}: the edge receives more than the center.\n#   * extension: finite surface rate D dc/dz = ks c at the wafer, Da = ks L/D.\n#     For a thin gap (L << R) the gap-averaged balance gives a Bessel problem:\n#       c = c_A0 I0(m r)/I0(m R),  m^2 = 2 ks/(D L),  Thiele modulus Phi = m R\n#     centre/edge deposition ratio = 1/I0(Phi): uniform wafers need Phi < ~0.5\n#     (reaction-limited LPCVD), which is why TEOS furnaces can stack wafers closely.\nusing Printf\n\nfunction rect_series(x, y; W = 1.0, H = 1.0, nterms = 101)\n    s = 0.0\n    for n in 1:2:nterms\n        a = n * pi / W\n        s += 4 / (n * pi) * sin(a * x) * exp(a * (y - H)) * (1 - exp(-2a * y)) / (1 - exp(-2a * H))\n    end\n    return s\nend\n\nfunction rect_sor(N = 40; omega = 1.85, tol = 1e-9)\n    c = zeros(N + 1, N + 1); c[N+1, 2:N] .= 1.0          # c[j, i], j = y index\n    for it in 1:20000\n        err = 0.0\n        for j in 2:N, i in 2:N\n            d = omega * (0.25 * (c[j, i-1] + c[j, i+1] + c[j-1, i] + c[j+1, i]) - c[j, i])\n            c[j, i] += d; err = max(err, abs(d))\n        end\n        err < tol && return c, it\n    end\n    return c, 20000\nend\n\nfunction I0(x)\n    s, term, k = 1.0, 1.0, 1\n    while true\n        term *= (x / (2k))^2; s += term\n        term < 1e-16 * s && return s\n        k += 1\n    end\nend\nthin_gap(r, R, Da, L) = (m = sqrt(2Da) / L; I0(m * r) / I0(m * R))\n\nfunction wafer_sor(Da; R = 1.0, L = 0.1, Nr = 80, Nz = 10, omega = 1.9, tol = 1e-10)\n    dr, dz = R / Nr, (L / 2) / Nz\n    ar, az, beta = 1 / dr^2, 1 / dz^2, 2dz * Da / L\n    c = zeros(Nz + 1, Nr + 1); c[:, Nr+1] .= 1.0         # row 1 = wafer (z = 0)\n    for it in 1:200000\n        err = 0.0\n        for j in 2:Nz+1, i in 1:Nr\n            up = j < Nz + 1 ? c[j+1, i] : c[j-1, i]; dn = c[j-1, i]\n            if i == 1\n                nw = (4ar * c[j, 2] + az * (up + dn)) / (4ar + 2az)\n            else\n                r = (i - 1) * dr; w = (1 - dr / (2r)) * ar; e = (1 + dr / (2r)) * ar\n                nw = (w * c[j, i-1] + e * c[j, i+1] + az * (up + dn)) / (2ar + 2az)\n            end\n            d = omega * (nw - c[j, i]); c[j, i] += d; err = max(err, abs(d))\n        end\n        for i in 1:Nr\n            nw = (4c[2, i] - c[3, i]) / (3 + beta); err = max(err, abs(nw - c[1, i])); c[1, i] = nw\n        end\n        err < tol && return c, it\n    end\n    return c, 200000\nend\n\nprintln(\"Rectangle W = H = 1, c/c0 at (x, y):\")\ncs, its = rect_sor()\nfor (x, y) in ((0.5, 0.5), (0.25, 0.75), (0.5, 0.9), (0.1, 0.5))\n    @printf(\"  (%.2f,%.2f)  series = %.5f   SOR(40x40) = %.5f\\n\", x, y, rect_series(x, y), cs[round(Int, y * 40)+1, round(Int, x * 40)+1])\nend\n@printf(\"  SOR iterations: %d    centre value exact = 0.25 by superposition\\n\", its)\n@printf(\"  Gibbs: partial sums at (0.02, 1.0): [%.4f, %.4f, %.4f]\\n\", (rect_series(0.02, 1.0; nterms = n) for n in (5, 21, 101))...)\nprintln(\"\\nTEOS wafer gap: R = 1, gap L = 0.1, Robin BC with Da = ks L/D\")\nprintln(\"  Thiele modulus Phi = R sqrt(2 Da)/L ; centre/edge deposition = 1/I0(Phi)\")\nprintln(\"  Da        Phi     FDM centre/edge   thin-gap 1/I0(Phi)   SOR its\")\nfor Da in (1e-4, 1e-3, 1e-2, 5e-2)\n    c, k = wafer_sor(Da)\n    @printf(\"  %7.1e  %6.3f   %.4f            %.4f             %d\\n\", Da, sqrt(2Da) / 0.1, c[1, 1], thin_gap(0, 1, Da, 0.1), k)\nend\nprintln(\"  radial profile at Da = 1e-2 (Phi = 1.414):\")\nc, _ = wafer_sor(1e-2)\nfor f in (0.0, 0.25, 0.5, 0.75, 1.0)\n    @printf(\"    r/R = %4.2f   FDM c_wafer = %.4f   thin-gap = %.4f\\n\", f, c[1, round(Int, f * 80)+1], thin_gap(f, 1, 1e-2, 0.1))\nend\n",
    cpp: "// Week 10 - Topic 4: Two-Dimensional Steady Diffusion (Laplace Equation)\n// Lecture (Part 2):\n//   * rectangle 0<x<W, 0<y<H: c = 0 on x=0, x=W, y=0; c = c0 on y=H\n//       c/c0 = sum_{n odd} (4/(n pi)) sin(n pi x/W) sinh(n pi y/W)/sinh(n pi H/W)\n//   * TEOS stagnant gas between two wafers (LPCVD furnace): cylindrical (r, z)\n//       (1/r) d/dr(r dc/dr) + d^2c/dz^2 = 0\n//       c = c_A0 at r = R (open edge), c = 0 at z = 0 (fast surface reaction on the wafer),\n//       dc/dr = 0 at r = 0, dc/dz = 0 at z = L/2 (mid-plane symmetry)\n//     deposition flux on the wafer N(r) = D dc/dz|_{z=0}: the edge receives more than the center.\n//   * extension: finite surface rate D dc/dz = ks c at the wafer, Da = ks L/D.\n//     For a thin gap (L << R) the gap-averaged balance gives a Bessel problem:\n//       c = c_A0 I0(m r)/I0(m R),  m^2 = 2 ks/(D L),  Thiele modulus Phi = m R\n//     centre/edge deposition ratio = 1/I0(Phi): uniform wafers need Phi < ~0.5\n//     (reaction-limited LPCVD), which is why TEOS furnaces can stack wafers closely.\n\n// Build: g++ -O2 -std=c++17 week10_topic4_laplace_2d.cpp -o topic4\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n#include <vector>\n\nconst double PI = 3.14159265358979323846;\nusing Grid = std::vector<std::vector<double>>;\n\ndouble rectSeries(double x, double y, double W = 1.0, double H = 1.0, int nterms = 101) {\n    double s = 0.0;\n    for (int n = 1; n <= nterms; n += 2) {\n        double a = n * PI / W;\n        double ratio = std::exp(a * (y - H)) * (1 - std::exp(-2 * a * y)) / (1 - std::exp(-2 * a * H));\n        s += 4 / (n * PI) * std::sin(a * x) * ratio;\n    }\n    return s;\n}\n\nint rectSOR(Grid& c, int N = 40, double omega = 1.85, double tol = 1e-9) {\n    c.assign(N + 1, std::vector<double>(N + 1, 0.0));\n    for (int i = 1; i < N; ++i) c[N][i] = 1.0;\n    for (int it = 0; it < 20000; ++it) {\n        double err = 0;\n        for (int j = 1; j < N; ++j)\n            for (int i = 1; i < N; ++i) {\n                double nw = 0.25 * (c[j][i - 1] + c[j][i + 1] + c[j - 1][i] + c[j + 1][i]);\n                double d = omega * (nw - c[j][i]); c[j][i] += d; err = std::fmax(err, std::fabs(d));\n            }\n        if (err < tol) return it + 1;\n    }\n    return 20000;\n}\n\ndouble I0(double x) {\n    double s = 1.0, term = 1.0;\n    for (int k = 1;; ++k) { term *= (x / (2 * k)) * (x / (2 * k)); s += term; if (term < 1e-16 * s) return s; }\n}\ndouble thinGap(double r, double R, double Da, double L) { double m = std::sqrt(2 * Da) / L; return I0(m * r) / I0(m * R); }\n\nint waferSOR(Grid& c, double Da, double R = 1.0, double L = 0.1, int Nr = 80, int Nz = 10, double omega = 1.9, double tol = 1e-10) {\n    double dr = R / Nr, dz = (L / 2) / Nz, ar = 1 / (dr * dr), az = 1 / (dz * dz), beta = 2 * dz * Da / L;\n    c.assign(Nz + 1, std::vector<double>(Nr + 1, 0.0));\n    for (int j = 0; j <= Nz; ++j) c[j][Nr] = 1.0;\n    for (int it = 0; it < 200000; ++it) {\n        double err = 0;\n        for (int j = 1; j <= Nz; ++j)\n            for (int i = 0; i < Nr; ++i) {\n                double up = j < Nz ? c[j + 1][i] : c[j - 1][i], dn = c[j - 1][i], nw;\n                if (i == 0) nw = (4 * ar * c[j][1] + az * (up + dn)) / (4 * ar + 2 * az);\n                else {\n                    double r = i * dr, w = (1 - dr / (2 * r)) * ar, e = (1 + dr / (2 * r)) * ar;\n                    nw = (w * c[j][i - 1] + e * c[j][i + 1] + az * (up + dn)) / (2 * ar + 2 * az);\n                }\n                double d = omega * (nw - c[j][i]); c[j][i] += d; err = std::fmax(err, std::fabs(d));\n            }\n        for (int i = 0; i < Nr; ++i) {\n            double nw = (4 * c[1][i] - c[2][i]) / (3 + beta);\n            err = std::fmax(err, std::fabs(nw - c[0][i])); c[0][i] = nw;\n        }\n        if (err < tol) return it + 1;\n    }\n    return 200000;\n}\n\nint main() {\n    Grid cs; int its = rectSOR(cs);\n    std::printf(\"Rectangle W = H = 1, c/c0 at (x, y):\\n\");\n    double pts[4][2] = {{0.5, 0.5}, {0.25, 0.75}, {0.5, 0.9}, {0.1, 0.5}};\n    for (auto& p : pts) {\n        int i = (int)std::lround(p[0] * 40), j = (int)std::lround(p[1] * 40);\n        std::printf(\"  (%.2f,%.2f)  series = %.5f   SOR(40x40) = %.5f\\n\", p[0], p[1], rectSeries(p[0], p[1]), cs[j][i]);\n    }\n    std::printf(\"  SOR iterations: %d    centre value exact = 0.25 by superposition\\n\", its);\n    std::printf(\"  Gibbs: partial sums at (0.02, 1.0): [%.4f, %.4f, %.4f]\\n\", rectSeries(0.02, 1, 1, 1, 5), rectSeries(0.02, 1, 1, 1, 21), rectSeries(0.02, 1, 1, 1, 101));\n\n    std::printf(\"\\nTEOS wafer gap: R = 1, gap L = 0.1, Robin BC with Da = ks L/D\\n\");\n    std::printf(\"  Thiele modulus Phi = R sqrt(2 Da)/L ; centre/edge deposition = 1/I0(Phi)\\n\");\n    std::printf(\"  Da        Phi     FDM centre/edge   thin-gap 1/I0(Phi)   SOR its\\n\");\n    Grid c;\n    for (double Da : {1e-4, 1e-3, 1e-2, 5e-2}) {\n        int k = waferSOR(c, Da);\n        std::printf(\"  %7.1e  %6.3f   %.4f            %.4f             %d\\n\", Da, std::sqrt(2 * Da) / 0.1, c[0][0], thinGap(0, 1, Da, 0.1), k);\n    }\n    std::printf(\"  radial profile at Da = 1e-2 (Phi = 1.414):\\n\");\n    waferSOR(c, 1e-2);\n    for (double f : {0.0, 0.25, 0.5, 0.75, 1.0}) {\n        int i = (int)std::lround(f * 80);\n        std::printf(\"    r/R = %4.2f   FDM c_wafer = %.4f   thin-gap = %.4f\\n\", f, c[0][i], thinGap(f, 1, 1e-2, 0.1));\n    }\n}\n",
  },
};

export default WEEK10_CODES;
